// Normaliza o evento do Tiny (mesmo código do workflow principal).
// O webhook pode chegar como JSON puro no body ou como form-urlencoded
// com o JSON dentro de um campo. Aqui os dois casos viram o mesmo formato.
const saida = [];
for (const item of $input.all()) {
  let b = item.json.body ?? item.json;
  if (typeof b === "string") { try { b = JSON.parse(b); } catch (e) {} }
  if (b && typeof b.dados === "string") { try { b = JSON.parse(b.dados); } catch (e) {} }
  if (b && b.payload) b = b.payload;
  const d = b?.dados ?? {};
  saida.push({ json: {
    tipo: b?.tipo ?? "",
    id: d.id ?? "",
    numero: d.numero ?? "",
    situacao: d.codigoSituacao ?? "",
    cnpj: b?.cnpj ?? "",
  }});
}
return saida;

// Gera uma linha por UNIDADE a produzir, no formato exato da aba PCP.
// Nome do card = "{pedido} - {descrição} (k/n)"
// MESMO código verificado contra as 758 linhas da PCP no workflow principal.

const tipo = $('Normalizar evento').first().json.tipo;
if (tipo !== 'inclusao_pedido') return [];

let p = {};
try {
  p = $('Tiny · pedido.obter').first().json?.retorno?.pedido ?? {};
} catch (e) {
  p = $('Tiny - pedido.obter').first().json?.retorno?.pedido ?? {};
}

// ARRUMAR do Sheets colapsa espaços internos, não só as pontas.
const norm = (v) => String(v ?? '').replace(/\s+/g, ' ').trim();

const pedido = norm(p.numero);
if (!pedido) return [];

// Prefixo de origem: distingue os cards da GreenPallets dos da Domoby na
// mesma coluna 'pedido' (as numerações das duas contas colidem).
// Para remover o prefixo no futuro, troque por ''.
const PREFIXO = 'GP-';

// data de entrega: dd/mm/yyyy -> ISO, meio-dia em Fortaleza
const prev = norm(p.data_prevista);
let dueISO = '';
if (/^\d{2}\/\d{2}\/\d{4}$/.test(prev)) {
  const [d, m, y] = prev.split('/').map(Number);
  dueISO = new Date(Date.UTC(y, m - 1, d, 15, 0, 0)).toISOString();
}

// expande cada item pela quantidade -> uma entrada por unidade
const lista = (v) => (Array.isArray(v) ? v : v ? [v] : []);
const unidades = [];
for (const raw of lista(p.itens)) {
  const i = raw.item || raw;
  const qtd = Math.round(parseFloat(String(i.quantidade ?? '0').replace(',', '.')) || 0);
  if (qtd < 1) continue;                        // item com quantidade 0 não vira card
  const base = `${PREFIXO}${pedido} - ${norm(i.descricao)}`;
  for (let k = 0; k < qtd; k++) unidades.push(base);
}

// marcador (k/n): n = quantas vezes aquele texto aparece dentro do pedido
const total = {};
for (const u of unidades) total[u] = (total[u] || 0) + 1;

const visto = {};
return unidades.map((u) => {
  visto[u] = (visto[u] || 0) + 1;
  return { json: {
    nomeCard: `${u} (${visto[u]}/${total[u]})`,
    dueDate: dueISO,
    pedido,
  }};
});
